INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8120930f-30da-5018-8aaf-b3fa5effe2ee', 'Vietnam Corporate Governance Code of Best Practices', 'Vietnam Corporate Governance Code of Best Practices, 2019', 'The Vietnam Corporate Governance Code of Best Practices has been developed to provide a collection of recommendations on best corporate governance practices primarily for Vietnamese public companies. Beside good practices which have been adopted in laws and regulations and adopted by companies, the Code also advocates for standards that go beyond the minimum requirements in legislation and regulations.', 'The Vietnam Corporate Governance Code of Best Practices has been developed to provide a collection of recommendations on best corporate governance practices primarily for Vietnamese public companies. Beside good practices which have been adopted in laws and regulations and adopted by companies, the Code also advocates for standards that go beyond the minimum requirements in legislation and regulations.', 'The Vietnam Corporate Governance Code of Best Practices has been developed to provide a collection of recommendations on best corporate governance practices primarily for Vietnamese public companies. Beside good practices which have been adopted in laws and regulations and adopted by companies, the Code also advocates for standards that go beyond the minimum requirements in legislation and regulations.', 'Vietnam', 'governance', 'in_force', '2019-01-01'::date, 'Vietnam', 'https://www.carrotsandsticks.org/policies/190_7', ARRAY['regulations', 'sdg16', 'disclosure', 'voluntary', 'vietnam']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6283efd1-c8c0-5864-b762-0834d2c4a82b', 'Vietnam SPP Guidelines Integrating Sustainability Criteria for CFLs into', 'SPP Guidelines Integrating Sustainability Criteria for CFLs into Public Procurement Procedures, 2017', 'SPP implementation in Vietnam will contribute directly to the SCP objectives defined by the Government of Vietnam in its National Action Plan for Sustainable Consumption and Production (January 2016). According to the Action Plan, SCP aims to transform production and consumption towards greater resource and energy efficiency, promote renewable material and energy sources; reuse, reduce, and recycle waste; and maintain ecological sustainability throughout the product life cycle -- from exploitation, input material, supply, production and processing, distribution, consumption, and disposal. In line with these SCP objectives, implementation of SPP will promote sustainable consumption and production practices through the prioritized acquisition of sustainable goods, works and services by public entities.', 'SPP implementation in Vietnam will contribute directly to the SCP objectives defined by the Government of Vietnam in its National Action Plan for Sustainable Consumption and Production (January 2016). According to the Action Plan, SCP aims to transform production and consumption towards greater resource and energy efficiency, promote renewable material and energy sources; reuse, reduce, and recycle waste; and maintain ecological sustainability throughout the product life cycle -- from exploitation, input material, supply, production and processing, distribution, consumption, and disposal. In line with these SCP objectives, implementation of SPP will promote sustainable consumption and production practices through the prioritized acquisition of sustainable goods, works and services by public entities.', 'SPP implementation in Vietnam will contribute directly to the SCP objectives defined by the Government of Vietnam in its National Action Plan for Sustainable Consumption and Production (January 2016). According to the Action Plan, SCP aims to transform production and consumption towards greater resource and energy efficiency, promote renewable material and energy sources; reuse, reduce, and recycle waste; and maintain ecological sustainability throughout the product life cycle -- from exploitation, input material, supply, production and processing, distribution, consumption, and disposal. In line with these SCP objectives, implementation of SPP will promote sustainable consumption and production practices through the prioritized acquisition of sustainable goods, works and services by public entities.', 'Vietnam', 'climate', 'in_force', '2017-01-01'::date, 'Vietnam', 'https://www.carrotsandsticks.org/policies/190_8', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg7', 'sdg12', 'voluntary', 'vietnam']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('641b01c9-ee79-5b9c-915f-2955b376b84a', 'Vietnam Guidelines for Information Disclosure on Securities Market', 'Circular on Guidelines for Information Disclosure on Securities Market, 2015', 'This Circular deals with information disclosure on Vietnam securities market.', 'This Circular deals with information disclosure on Vietnam securities market.', 'This Circular deals with information disclosure on Vietnam securities market.', 'Vietnam', 'governance', 'in_force', '2015-01-01'::date, 'Vietnam', 'https://www.carrotsandsticks.org/policies/190_1', ARRAY['guidance_frameworks', 'voluntary', 'vietnam', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5a0b4505-e8f9-5ed2-a142-0ee9589f2e54', 'Vietnam Environmental & Social Disclosure Guide', 'Environmental & Social Disclosure Guide, 2014', 'This Guide provides additional guidance to report preparers in complying with Circular 155/2015/TT-BTC dated 6 October 2015 on public disclosure for stock exchanges. This Guide provides guidance on the performance indicators required under Article 8, Item 2, Chapter II and Appendix 4 on Annual Reports of Circular 155/2015/TT-BTC.', 'This Guide provides additional guidance to report preparers in complying with Circular 155/2015/TT-BTC dated 6 October 2015 on public disclosure for stock exchanges. This Guide provides guidance on the performance indicators required under Article 8, Item 2, Chapter II and Appendix 4 on Annual Reports of Circular 155/2015/TT-BTC.', 'This Guide provides additional guidance to report preparers in complying with Circular 155/2015/TT-BTC dated 6 October 2015 on public disclosure for stock exchanges. This Guide provides guidance on the performance indicators required under Article 8, Item 2, Chapter II and Appendix 4 on Annual Reports of Circular 155/2015/TT-BTC.', 'Vietnam', 'climate', 'in_force', '2014-01-01'::date, 'Vietnam', 'https://www.carrotsandsticks.org/policies/190_2', ARRAY['guidance_frameworks', 'mandatory', 'vietnam', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('04a6845b-2aa8-5c86-9dc6-3569dcb4e46b', 'Sustainability Reporting Handbook for Vietnamese Companies', 'Sustainability Reporting Handbook for Vietnamese Companies, 2013', 'This guideline provides companies in Vietnam with some simple steps to follow to get started in sustainability reporting. in particular, it focuses on environmental and social (e&S) aspects of business performance.', 'This guideline provides companies in Vietnam with some simple steps to follow to get started in sustainability reporting. in particular, it focuses on environmental and social (e&S) aspects of business performance.', 'This guideline provides companies in Vietnam with some simple steps to follow to get started in sustainability reporting. in particular, it focuses on environmental and social (e&S) aspects of business performance.', 'Vietnam', 'climate', 'in_force', '2013-01-01'::date, 'Vietnam', 'https://www.carrotsandsticks.org/policies/190_3', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'vietnam']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0c9aed49-adea-514e-86f3-e3d7a0b792e8', 'Vietnam Viet Nam Sustainable Development Strategy for', 'Viet Nam Sustainable Development Strategy for 2011-2020', 'Its main objective is sustainable and effective growth, along with social progress and equality, national resources and environment protection, socio-political stability, firm protection of independence-sovereignty-unification and territorial integrity of the country. Sets national targets, but nothing on sustainability reporting.', 'Its main objective is sustainable and effective growth, along with social progress and equality, national resources and environment protection, socio-political stability, firm protection of independence-sovereignty-unification and territorial integrity of the country. Sets national targets, but nothing on sustainability reporting.', 'Its main objective is sustainable and effective growth, along with social progress and equality, national resources and environment protection, socio-political stability, firm protection of independence-sovereignty-unification and territorial integrity of the country. Sets national targets, but nothing on sustainability reporting.', 'Vietnam', 'climate', 'in_force', '2012-01-01'::date, 'Vietnam', 'https://www.carrotsandsticks.org/policies/190_4', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'vietnam']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8af6e664-b485-528d-8cd9-5d739bec20cf', 'Vietnam QH10 Law on Enterprises', 'No. 13/1999/QH10 Law on Enterprises', 'The Law provides the obligations and expectations around the establishment, management, organization and operation of limited liability companies, shareholding companies, partnerships and private enterprises. For all such enterprises, the Law provides the annual disclosure requirements, including the contents and expected time of submission/publication. Dependent on the enterprise, the annual financial statements are to be submitted to the tax office, business registration and shareholders.', 'The Law provides the obligations and expectations around the establishment, management, organization and operation of limited liability companies, shareholding companies, partnerships and private enterprises. For all such enterprises, the Law provides the annual disclosure requirements, including the contents and expected time of submission/publication. Dependent on the enterprise, the annual financial statements are to be submitted to the tax office, business registration and shareholders.', 'The Law provides the obligations and expectations around the establishment, management, organization and operation of limited liability companies, shareholding companies, partnerships and private enterprises. For all such enterprises, the Law provides the annual disclosure requirements, including the contents and expected time of submission/publication. Dependent on the enterprise, the annual financial statements are to be submitted to the tax office, business registration and shareholders.', 'Vietnam', 'governance', 'in_force', '1999-01-01'::date, 'Vietnam', 'https://www.carrotsandsticks.org/policies/190_9', ARRAY['regulations', 'sdg17', 'mandatory', 'disclosure', 'vietnam']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c3680e40-97c0-5f3e-a50e-c355b4f7ec3a', 'Zambia Corporate Governance Code for Listed Companies', 'Corporate Governance Code for Listed Companies, 2021', 'This aim of this code is to promote good governance practices and enhance the transparency and accountability of companies listed on the exchange. The code establishes guidelines for the composition and responsibilities of the board of directors, including the appointment of independent directors and the establishment of board committees. It also outlines requirements for financial reporting and disclosure, including the publication of annual reports and the disclosure of related party transactions. Additionally, the code sets out principles for the management of risk, the protection of shareholder rights, and the promotion of ethical conduct and corporate social responsibility. The LuSE Corporate Governance Code for Listed Companies is intended to promote the adoption of best practices in corporate governance among listed companies in Zambia, and to strengthen investor confidence in the market by ensuring that companies are well-managed and transparent in their operations.', 'This aim of this code is to promote good governance practices and enhance the transparency and accountability of companies listed on the exchange. The code establishes guidelines for the composition and responsibilities of the board of directors, including the appointment of independent directors and the establishment of board committees. It also outlines requirements for financial reporting and disclosure, including the publication of annual reports and the disclosure of related party transactions. Additionally, the code sets out principles for the management of risk, the protection of shareholder rights, and the promotion of ethical conduct and corporate social responsibility. The LuSE Corporate Governance Code for Listed Companies is intended to promote the adoption of best practices in corporate governance among listed companies in Zambia, and to strengthen investor confidence in the market by ensuring that companies are well-managed and transparent in their operations.', 'This aim of this code is to promote good governance practices and enhance the transparency and accountability of companies listed on the exchange. The code establishes guidelines for the composition and responsibilities of the board of directors, including the appointment of independent directors and the establishment of board committees. It also outlines requirements for financial reporting and disclosure, including the publication of annual reports and the disclosure of related party transactions. Additionally, the code sets out principles for the management of risk, the protection of shareholder rights, and the promotion of ethical conduct and corporate social responsibility. The LuSE Corporate Governance Code for Listed Companies is intended to promote the adoption of best practices in corporate governance among listed companies in Zambia, and to strengthen investor confidence in the market by ensuring that companies are well-managed and transparent in their operations.', 'Zambia', 'climate', 'in_force', '2021-01-01'::date, 'Zambia', 'https://www.carrotsandsticks.org/policies/192_1', ARRAY['regulations', 'mandatory', 'zambia', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4e7da2b0-61d6-518c-8109-db74ff8ac5b1', 'Zambia Companies Bill', 'The Companies Bill, 2017', 'The Zambian government introduced The Companies Bill, 2017, which aimed to modernize and consolidate the laws governing companies in Zambia. The bill establishes new requirements for the incorporation and registration of companies, including the creation of a single online registry for companies and the adoption of electronic filing and signatures. It also introduces new rules on corporate governance, including requirements for the appointment of independent directors and the establishment of audit committees. The bill also includes provisions for the protection of minority shareholders and the prevention of corporate abuse, such as related party transactions and insider trading. It also establishes new rules for the management and resolution of conflicts of interest, and introduces penalties for non-compliance with the provisions of the bill. The Companies Bill, 2017 is intended to promote transparency, accountability, and good governance in the management of companies in Zambia, and to ensure that the country''s business environment is conducive to investment and economic growth.', 'The Zambian government introduced The Companies Bill, 2017, which aimed to modernize and consolidate the laws governing companies in Zambia. The bill establishes new requirements for the incorporation and registration of companies, including the creation of a single online registry for companies and the adoption of electronic filing and signatures. It also introduces new rules on corporate governance, including requirements for the appointment of independent directors and the establishment of audit committees. The bill also includes provisions for the protection of minority shareholders and the prevention of corporate abuse, such as related party transactions and insider trading. It also establishes new rules for the management and resolution of conflicts of interest, and introduces penalties for non-compliance with the provisions of the bill. The Companies Bill, 2017 is intended to promote transparency, accountability, and good governance in the management of companies in Zambia, and to ensure that the country''s business environment is conducive to investment and economic growth.', 'The Zambian government introduced The Companies Bill, 2017, which aimed to modernize and consolidate the laws governing companies in Zambia. The bill establishes new requirements for the incorporation and registration of companies, including the creation of a single online registry for companies and the adoption of electronic filing and signatures. It also introduces new rules on corporate governance, including requirements for the appointment of independent directors and the establishment of audit committees. The bill also includes provisions for the protection of minority shareholders and the prevention of corporate abuse, such as related party transactions and insider trading. It also establishes new rules for the management and resolution of conflicts of interest, and introduces penalties for non-compliance with the provisions of the bill. The Companies Bill, 2017 is intended to promote transparency, accountability, and good governance in the management of companies in Zambia, and to ensure that the country''s business environment is conducive to investment and economic growth.', 'Zambia', 'nature', 'in_force', '2016-01-01'::date, 'Zambia', 'https://www.carrotsandsticks.org/policies/192_2', ARRAY['regulations', 'mandatory', 'zambia', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a6a17fa5-4019-5be8-9a70-96d1db1038d3', 'Zambia Mines and Minerals Development Act', 'The Mines and Minerals Development Act, 2015', 'An Act to revise the law relating to the exploration for, mining and processing of, minerals; provide for safety, health and environmental protection in mining operations; provide for the establishment of the Mining Appeals Tribunal; repeal and replace the Mines and Minerals Development Act, 2008; and provide for matters connected with, or incidental to, the foregoing.', 'An Act to revise the law relating to the exploration for, mining and processing of, minerals; provide for safety, health and environmental protection in mining operations; provide for the establishment of the Mining Appeals Tribunal; repeal and replace the Mines and Minerals Development Act, 2008; and provide for matters connected with, or incidental to, the foregoing.', 'An Act to revise the law relating to the exploration for, mining and processing of, minerals; provide for safety, health and environmental protection in mining operations; provide for the establishment of the Mining Appeals Tribunal; repeal and replace the Mines and Minerals Development Act, 2008; and provide for matters connected with, or incidental to, the foregoing.', 'Zambia', 'climate', 'in_force', '2015-01-01'::date, 'Zambia', 'https://www.carrotsandsticks.org/policies/192_3', ARRAY['regulations', 'mandatory', 'zambia', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1a66d718-bd52-51dc-97db-bcee7b326ce7', 'Zimbabwe Statutory Instrument 134 of', 'Statutory Instrument 134 of 2019', 'Statutory Instrument 134 of 2019 being the Securities and Exchange (Zimbabwe Stock Exchange Listing Requirements) Rules 2 of 2019.  These Rules are extensive (213 pages) and impact upon the provisions of the Companies Act in regard to public companies.', 'Statutory Instrument 134 of 2019 being the Securities and Exchange (Zimbabwe Stock Exchange Listing Requirements) Rules 2 of 2019.  These Rules are extensive (213 pages) and impact upon the provisions of the Companies Act in regard to public companies.', 'Statutory Instrument 134 of 2019 being the Securities and Exchange (Zimbabwe Stock Exchange Listing Requirements) Rules 2 of 2019.  These Rules are extensive (213 pages) and impact upon the provisions of the Companies Act in regard to public companies.', 'Zimbabwe', 'governance', 'in_force', '2019-01-01'::date, 'Zimbabwe', 'https://www.carrotsandsticks.org/policies/193_3', ARRAY['mandatory', 'other sustainability policy', 'zimbabwe', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aedaddfe-6acd-586b-9e12-37dfba56adc6', 'Securities and Exchange (Zimbabwe Stock Exchange Listings Requirements) Rules', 'Securities and Exchange (Zimbabwe Stock Exchange Listings Requirements) Rules, 2019', 'In line with sections 399 to 404 of ZSE Listing Rules Issuers must disclose, in their Chairman’s statement of the Annual Report, sustainability information and the organisation’s strategy for addressing sustainability issues.', 'In line with sections 399 to 404 of ZSE Listing Rules Issuers must disclose, in their Chairman’s statement of the Annual Report, sustainability information and the organisation’s strategy for addressing sustainability issues.', 'In line with sections 399 to 404 of ZSE Listing Rules Issuers must disclose, in their Chairman’s statement of the Annual Report, sustainability information and the organisation’s strategy for addressing sustainability issues.', 'Zimbabwe', 'climate', 'in_force', '2019-01-01'::date, 'Zimbabwe', 'https://www.carrotsandsticks.org/policies/193_5', ARRAY['sdg13', 'mandatory', 'sdg16', 'mandatory_regulations', 'zimbabwe', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c19fdd00-a948-5bb1-84f8-9ee3dd1ddc89', 'Zimbabwe Companies and Other Business Entities Act', 'Companies and Other Business Entities Act 2019', 'Replacing outdated statutes, Zimbabwe''s 2019 Companies and Other Business Entities Act modernizes business regulations. From company formation and governance to winding up, it provides a comprehensive framework for all business entities, including companies, public business corporations, and registered businesses. The Act prioritizes transparency, streamlining registration and reporting processes. It also tackles defunct entities through re-registration, aiming for a clean and efficient business landscape.', 'Replacing outdated statutes, Zimbabwe''s 2019 Companies and Other Business Entities Act modernizes business regulations. From company formation and governance to winding up, it provides a comprehensive framework for all business entities, including companies, public business corporations, and registered businesses. The Act prioritizes transparency, streamlining registration and reporting processes. It also tackles defunct entities through re-registration, aiming for a clean and efficient business landscape.', 'Replacing outdated statutes, Zimbabwe''s 2019 Companies and Other Business Entities Act modernizes business regulations. From company formation and governance to winding up, it provides a comprehensive framework for all business entities, including companies, public business corporations, and registered businesses. The Act prioritizes transparency, streamlining registration and reporting processes. It also tackles defunct entities through re-registration, aiming for a clean and efficient business landscape.', 'Zimbabwe', 'climate', 'in_force', '2019-01-01'::date, 'Zimbabwe', 'https://www.carrotsandsticks.org/policies/193_7', ARRAY['regulations', 'mandatory', 'sdg16', 'zimbabwe', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ef6793c0-6eca-5347-b0db-0b0605dd1c00', 'Zimbabwe Public Entities Corporate Governance Act', 'The Public Entities Corporate Governance Act', 'Launched in 2018, Zimbabwe''s Public Entities Corporate Governance Act revamps governance across state-owned entities. Aiming for transparency and accountability, it standardizes board appointments, sets compensation regulations, and outlines reporting requirements. It also addresses risk management, environmental impacts, and human resource practices. By strengthening corporate governance in public entities, the Act seeks to boost efficiency, reduce corruption, and ultimately achieve better outcomes for public services and the economy.', 'Launched in 2018, Zimbabwe''s Public Entities Corporate Governance Act revamps governance across state-owned entities. Aiming for transparency and accountability, it standardizes board appointments, sets compensation regulations, and outlines reporting requirements. It also addresses risk management, environmental impacts, and human resource practices. By strengthening corporate governance in public entities, the Act seeks to boost efficiency, reduce corruption, and ultimately achieve better outcomes for public services and the economy.', 'Launched in 2018, Zimbabwe''s Public Entities Corporate Governance Act revamps governance across state-owned entities. Aiming for transparency and accountability, it standardizes board appointments, sets compensation regulations, and outlines reporting requirements. It also addresses risk management, environmental impacts, and human resource practices. By strengthening corporate governance in public entities, the Act seeks to boost efficiency, reduce corruption, and ultimately achieve better outcomes for public services and the economy.', 'Zimbabwe', 'climate', 'in_force', '2018-01-01'::date, 'Zimbabwe', 'https://www.carrotsandsticks.org/policies/193_6', ARRAY['regulations', 'mandatory', 'sdg16', 'zimbabwe', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('101b60d3-ce20-5ee3-b631-3bc32f5f0714', 'Zimbabwe Mines and Minerals Act (Chapter 21:05)', 'Mines and Minerals Act (Chapter 21:05)', 'Zimbabwe''s Mines and Minerals Act controls the industry, granting licenses and ensuring responsible resource development. It defines rights and duties for miners, enforces environmental and safety standards, and collects revenue for the nation. This framework promotes responsible mining practices while balancing benefits with regulations.', 'Zimbabwe''s Mines and Minerals Act controls the industry, granting licenses and ensuring responsible resource development. It defines rights and duties for miners, enforces environmental and safety standards, and collects revenue for the nation. This framework promotes responsible mining practices while balancing benefits with regulations.', 'Zimbabwe''s Mines and Minerals Act controls the industry, granting licenses and ensuring responsible resource development. It defines rights and duties for miners, enforces environmental and safety standards, and collects revenue for the nation. This framework promotes responsible mining practices while balancing benefits with regulations.', 'Zimbabwe', 'climate', 'in_force', '2016-01-01'::date, 'Zimbabwe', 'https://www.carrotsandsticks.org/policies/193_4', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'zimbabwe', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('023eddc8-0935-5677-8007-487eb9c4d724', 'Zimbabwe Zibabwe National Code of Corporate Governance', 'Zibabwe National Code of Corporate Governance, 2015', 'The Code has been amended, sets out standard corporate governance structures and regulations, and now it also requires companies to produce sustainability reports using GRI or IIRC.', 'The Code has been amended, sets out standard corporate governance structures and regulations, and now it also requires companies to produce sustainability reports using GRI or IIRC.', 'The Code has been amended, sets out standard corporate governance structures and regulations, and now it also requires companies to produce sustainability reports using GRI or IIRC.', 'Zimbabwe', 'climate', 'in_force', '2015-01-01'::date, 'Zimbabwe', 'https://www.carrotsandsticks.org/policies/193_1', ARRAY['regulations', 'mandatory', 'sdg16', 'zimbabwe', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('55d841a0-a006-5a87-80c2-a680c2106af5', 'Zimbabwe Zibabwe Stock Exchange Listing Requirements', 'Zibabwe Stock Exchange Listing Requirements, 2002', 'These listings requirements set out in this binder apply to both applicants for listing and presently listed companies. The listing requirements reflect, inter alia, the rules and procedures governing new applications, proposed marketing of securities and the continuing obligations of issuers, and are aimed at ensuring that the business of the ZSE is carried on with due regard to the public interest.', 'These listings requirements set out in this binder apply to both applicants for listing and presently listed companies. The listing requirements reflect, inter alia, the rules and procedures governing new applications, proposed marketing of securities and the continuing obligations of issuers, and are aimed at ensuring that the business of the ZSE is carried on with due regard to the public interest.', 'These listings requirements set out in this binder apply to both applicants for listing and presently listed companies. The listing requirements reflect, inter alia, the rules and procedures governing new applications, proposed marketing of securities and the continuing obligations of issuers, and are aimed at ensuring that the business of the ZSE is carried on with due regard to the public interest.', 'Zimbabwe', 'governance', 'in_force', '2002-01-01'::date, 'Zimbabwe', 'https://www.carrotsandsticks.org/policies/193_2', ARRAY['guidance_frameworks', 'mandatory', 'other sustainability policy', 'zimbabwe']::text[]) ON CONFLICT (id) DO NOTHING;
